import { ApWebType } from "./ApWebInterface";

/**
 * 存放在window.name裡面的資料結構, 用來存放遊戲啟動可讀取的參數
 */
export class ApWebBase {
    protected _mode: ApWebType = "ap-none"; // 模式
    protected _closeInGameBuyFeature = false;
    protected _closeInGameOpenPromo = false;
    protected _useInGameEventCenterButton = false;
    public set closeInGameBuyFeature(value: boolean) { this._closeInGameBuyFeature = value; }
    public set closeInGameOpenPromo(value: boolean) { this._closeInGameOpenPromo = value; }
    public set useInGameEventCenterButton(value: boolean) { this._useInGameEventCenterButton = value; }
    public setMode(mode: ApWebType) { this._mode = mode; }
    public get mode(): ApWebType { return this._mode; }
    /** 是否使用ApWebSocket */
    public get isUseApSocket(): boolean {
        return this.mode === "ap-bridge" || this.mode === "ap-cover"
    }
    /** 遊戲是否在離線模式下運行 */
    public get isOfflineMode(): boolean { 
        return this.mode === "ap-master";
    }
    /** 是否關閉左上角遊戲名稱 */
    public get isCloseGameName(): boolean {
        return this.mode === "ap-cover" ||
            this.mode === "ap-bridge" ||
            this.mode === "ap-history" ||
            this.mode === "ap-replay" ||
            this.mode === "ap-replay-game-ui";
    }
    /** 是否在關閉遊戲內建的UI */
    public get isCloseInGameUi(): boolean {
        return this.mode === "ap-cover" || 
            this.mode === "ap-master" ||
            this.mode === "ap-history" ||
            this.mode === "ap-replay";
    }
    /** 是否使用ApWeb覆蓋遊戲UI */
    public get isUseInGameUI(): boolean {
        return !this.isCloseInGameUi;
    }
    /** 遊戲是否需要Handler處理與父窗口的通訊 */
    public get isNeedHandler(): boolean {
        return this.mode === "ap-cover" ||
            this.mode === "ap-bridge" ||
            this.mode === "ap-master" ||
            this.mode === "ap-history" ||
            this.mode === "ap-replay" ||
            this.mode === "ap-replay-game-ui";
    }
    /** 是否回傳重播時候的Bet */
    public get isReturnBetInReplay(): boolean {
        return this.mode === "ap-replay" || this.mode === "ap-replay-game-ui";
    }
    /** 將Buy Feature按鈕的功能由ApWeb處理 */
    public get isBuyFeatureToApWeb():boolean {
        return this.mode === "ap-cover" || this.mode === "ap-master" || (this.mode === "ap-bridge" && this._closeInGameBuyFeature);
    }
    /** 將open promo按鈕的功能由ApWeb處理 */
    public get isOpenPromoToApWeb():boolean {
        return this.mode === "ap-cover" || this.mode === "ap-master" || (this.mode === "ap-bridge" && this._closeInGameOpenPromo);
    }
    public get isAddEventCenterButton(): boolean {
        return this.mode === "ap-bridge" && this._useInGameEventCenterButton;
    }
    /** 是否需要替換轉址由ApWeb處理 */
    public get isReplaceRedirection(): boolean {
        return this.mode === "ap-bridge" || this.mode === "ap-cover"  || this.mode === "ap-master"
    }
    /** 是否啟用橫向佈局 */
    public get isEnableLandscape(): boolean {
        return this.mode === "ap-cover" || this.mode === "ap-replay";
    }
    /** 解析JSON */
    constructor(json?: string){
        // 需要用catch包起來, 因為有可能會parse失敗
        try {
            if (json) {
                const obj = JSON.parse(json);
                for (const key in obj) {
                    if (this.hasOwnProperty(key)) {
                        (this as any)[key] = obj[key];
                    }
                }
            }
        }
        catch (e) {

        }
    }

    public toString(): string {
        return JSON.stringify(this);
    }
}