import { ApWebMessageMap } from "./ApWebInterface";

export type ApWebMessages = {
    [K in keyof ApWebMessageMap]: { type: K; content: ApWebMessageMap[K] };
}[keyof ApWebMessageMap];

export function createApWebMessage<T extends keyof ApWebMessageMap>(
    type: T,
    content?: ApWebMessageMap[T]
): ApWebMessages {
    return { type, content } as ApWebMessages;
}